-- D-045：第一版 schema，以 PR 當時的 entity 對應為準（Hibernate Oracle12cDialect 產生後依 D-045 第 5 點調整）。
-- 寫法須同時能在 Oracle 19c 與 H2 Oracle 相容模式執行：
--   * 文字一律 VARCHAR2(n CHAR)：Oracle 預設以位元組計長度，UTF-8 中文一字 3 位元組。
--   * 長文字用 CLOB（Oracle 沒有 TEXT）。
--   * 布林值用 NUMBER(1,0)（19c 沒有 boolean）。
--   * 自動編號用 GENERATED BY DEFAULT AS IDENTITY。
--   * 表名與欄位名不使用 Oracle 保留字（review_submission 的評語欄位因此是 comment_text）。

create table audit_trail (
    id varchar2(36 char) not null,
    action varchar2(50 char) not null,
    actor_user_id varchar2(50 char) not null,
    actor_user_name varchar2(100 char) not null,
    detail clob,
    entity_id varchar2(36 char) not null,
    entity_type varchar2(50 char) not null,
    hospital_id varchar2(50 char),
    occurred_at timestamp not null,
    constraint pk_audit_trail primary key (id)
);

create table his_staff_directory (
    directory_entry_id number(19,0) generated by default as identity,
    active number(1,0) not null,
    candidate_role varchar2(255 char) not null,
    display_name varchar2(255 char) not null,
    hospital_id varchar2(255 char) not null,
    staff_id varchar2(255 char) not null,
    constraint pk_his_staff_directory primary key (directory_entry_id),
    constraint uk_his_staff_directory_scope_role unique (hospital_id, staff_id, candidate_role)
);

create table review_project (
    project_id varchar2(255 char) not null,
    bound_score_sheet_id varchar2(255 char),
    description varchar2(255 char),
    hospital_id varchar2(255 char) not null,
    initial_review_weight number(3,2),
    name varchar2(255 char) not null,
    quality_threshold number(10,2),
    rereview_weight number(3,2),
    status varchar2(255 char) not null,
    version_number number(10,0) not null,
    version_published number(1,0) not null,
    constraint pk_review_project primary key (project_id)
);

create table review_project_record_types (
    project_id varchar2(255 char) not null,
    record_type varchar2(255 char),
    constraint fk_review_project_record_types_project foreign key (project_id) references review_project (project_id)
);

create table review_case (
    case_id varchar2(255 char) not null,
    batch_id varchar2(255 char) not null,
    cancel_reason varchar2(255 char),
    cancelled_at timestamp,
    closed_at timestamp,
    due_at timestamp,
    final_conclusion varchar2(255 char),
    final_score number(10,2),
    hospital_id varchar2(255 char),
    initial_review_score number(10,2),
    latest_initial_submission_id varchar2(255 char),
    latest_rereview_submission_id varchar2(255 char),
    medical_record_type varchar2(255 char),
    project_id varchar2(255 char) not null,
    rereview_required number(1,0),
    rereviewer_assigned_at timestamp,
    rereviewer_due_at timestamp,
    rereviewer_id varchar2(255 char),
    return_reason varchar2(255 char),
    reviewer_assigned_at timestamp,
    reviewer_id varchar2(255 char),
    rule_snapshot_ref varchar2(255 char),
    score_sheet_version_ref varchar2(255 char),
    source_case_key varchar2(255 char),
    status varchar2(255 char) not null,
    constraint pk_review_case primary key (case_id)
);

create table review_submission (
    submission_id varchar2(255 char) not null,
    answer_set_json clob,
    attachment_refs_json clob,
    based_on_score_sheet_version_id varchar2(255 char),
    case_id varchar2(255 char) not null,
    comment_text varchar2(255 char),
    created_at timestamp,
    reviewer_id varchar2(255 char) not null,
    revision_no number(10,0),
    stage varchar2(255 char) not null,
    status varchar2(255 char) not null,
    submitted_at timestamp,
    superseded_by_submission_id varchar2(255 char),
    total_score number(10,2),
    updated_at timestamp,
    constraint pk_review_submission primary key (submission_id)
);

create table sampling_batch (
    batch_id varchar2(255 char) not null,
    eligible_count number(10,0),
    excluded_count number(10,0),
    execution_mode varchar2(255 char) not null,
    failure_reason varchar2(255 char),
    finished_at timestamp,
    population_count number(10,0),
    project_id varchar2(255 char) not null,
    project_version_id varchar2(255 char),
    project_version_number number(10,0),
    retry_of_batch_id varchar2(255 char),
    sampling_policy varchar2(255 char),
    score_sheet_version_id varchar2(255 char),
    selected_count number(10,0),
    snapshot_summary varchar2(2000 char),
    started_at timestamp,
    status varchar2(255 char) not null,
    constraint pk_sampling_batch primary key (batch_id)
);

create table sampling_batch_selected_case (
    id number(19,0) generated by default as identity,
    hospital_id varchar2(255 char) not null,
    medical_record_type varchar2(255 char) not null,
    source_case_key varchar2(255 char) not null,
    batch_id varchar2(255 char),
    constraint pk_sampling_batch_selected_case primary key (id),
    constraint uq_sampling_batch_selected_case_batch_source unique (batch_id, source_case_key),
    constraint fk_sampling_batch_selected_case_batch foreign key (batch_id) references sampling_batch (batch_id)
);

create table score_sheet (
    score_sheet_id varchar2(255 char) not null,
    project_id varchar2(255 char) not null,
    status varchar2(255 char) not null,
    version number(10,0) not null,
    constraint pk_score_sheet primary key (score_sheet_id)
);

create table score_sheet_section (
    id number(19,0) generated by default as identity,
    section_id varchar2(255 char) not null,
    title varchar2(255 char) not null,
    score_sheet_id varchar2(255 char),
    section_order number(10,0),
    constraint pk_score_sheet_section primary key (id),
    constraint fk_score_sheet_section_sheet foreign key (score_sheet_id) references score_sheet (score_sheet_id)
);

create table score_sheet_item (
    id number(19,0) generated by default as identity,
    code varchar2(255 char) not null,
    condition_expression varchar2(255 char),
    item_id varchar2(255 char) not null,
    max_score number(19,2) not null,
    required_rule varchar2(255 char) not null,
    score_type varchar2(255 char) not null,
    title varchar2(255 char) not null,
    weight number(19,2) not null,
    section_id number(19,0),
    item_order number(10,0),
    constraint pk_score_sheet_item primary key (id),
    constraint fk_score_sheet_item_section foreign key (section_id) references score_sheet_section (id)
);
